import numpy as np
from collections import Counter

def components(g):
    g=np.array(g); H,W=g.shape
    seen=np.zeros_like(g,bool); comps=[]
    for y in range(H):
        for x in range(W):
            if g[y,x] and not seen[y,x]:
                col=g[y,x]; stack=[(y,x)]; seen[y,x]=True; cells=[]
                while stack:
                    cy,cx=stack.pop(); cells.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==col and not seen[ny,nx]:
                            seen[ny,nx]=True; stack.append((ny,nx))
                comps.append((int(col),sorted(cells)))
    return comps

def shape(cells):
    ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
    y0,x0=min(ys),min(xs)
    return tuple(sorted((y-y0,x-x0) for y,x in cells)), (y0,x0)

def has_hole(g, cells):
    g=np.array(g); H,W=g.shape
    m=np.zeros_like(g,bool)
    for y,x in cells: m[y,x]=True
    # flood zeros from border
    out=np.zeros_like(g,bool); stack=[]
    for x in range(W):
        for y in (0,H-1):
            if not m[y,x] and not out[y,x]: out[y,x]=True; stack.append((y,x))
    for y in range(H):
        for x in (0,W-1):
            if not m[y,x] and not out[y,x]: out[y,x]=True; stack.append((y,x))
    while stack:
        cy,cx=stack.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=cy+dy,cx+dx
            if 0<=ny<H and 0<=nx<W and not m[ny,nx] and not out[ny,nx]:
                out[ny,nx]=True; stack.append((ny,nx))
    holes=[(y,x) for y in range(H) for x in range(W) if not m[y,x] and not out[y,x]]
    return len(holes)>0, holes

