import numpy as np

def comps_of(g):
    g=np.array(g); H,W=g.shape; seen=np.zeros_like(g,bool); out=[]
    for y in range(H):
        for x in range(W):
            if g[y,x] and not seen[y,x]:
                col=int(g[y,x]); st=[(y,x)]; seen[y,x]=1; cl=[]
                while st:
                    cy,cx=st.pop(); cl.append((cy,cx))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<H and 0<=nx<W and g[ny,nx]==col and not seen[ny,nx]:
                            seen[ny,nx]=1; st.append((ny,nx))
                out.append({'col':col,'cells':sorted(cl)})
    return out

def hole_cells(g, cells):
    g=np.array(g); H,W=g.shape
    m=np.zeros_like(g,bool)
    for y,x in cells: m[y,x]=True
    out=np.zeros_like(g,bool); st=[]
    for x in range(W):
        for y in (0,H-1):
            if not m[y,x] and not out[y,x]: out[y,x]=1; st.append((y,x))
    for y in range(H):
        for x in (0,W-1):
            if not m[y,x] and not out[y,x]: out[y,x]=1; st.append((y,x))
    while st:
        cy,cx=st.pop()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=cy+dy,cx+dx
            if 0<=ny<H and 0<=nx<W and not m[ny,nx] and not out[ny,nx]:
                out[ny,nx]=1; st.append((ny,nx))
    return [(y,x) for y in range(H) for x in range(W) if not m[y,x] and not out[y,x]]

def sym_dist1(cells):
    # return repaired cellset if exactly one single-cell move yields vertical-mirror symmetry
    ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
    w=max(xs)-min(xs)+1
    def sym(cs):
        s=set(cs)
        return all((y, min(xs)+max(xs)-x) in s for y,x in cs)
    if sym(cells): return None
    for c in cells:
        for x in range(min(xs), max(xs)+1):
            if (c[0],x) not in cells:
                nc=[q for q in cells if q!=c]+[(c[0],x)]
                if sym(nc): return sorted(nc)
    return None

def transform2(grid):
    g=np.array(grid); H,W=g.shape
    cs=comps_of(grid)
    info=[]
    for c in cs:
        hh=hole_cells(grid,c['cells'])
        ys=[p[0] for p in c['cells']]; xs=[p[1] for p in c['cells']]
        info.append({'col':c['col'],'cells':c['cells'],'hole':len(hh)>0,
                     'top':min(ys),'bot':max(ys),'cols':set(xs),'left':min(xs)})
    canvas=np.zeros_like(g)
    # hollow rise: closest-to-top first; blocked per column-overlap by already-placed
    hollows=sorted([o for o in info if o['hole']], key=lambda o:(o['top'],o['left']))
    placed_top={}
    for o in hollows:
        h=max(p[0] for p in o['cells'])-min(p[0] for p in o['cells'])+1
        r=0
        while True:
            conflict=False
            for q in placed_top.values():
                if o['cols'] & q['cols'] and r < q['r']+q['h'] and r+h > q['r']:
                    conflict=True; r=q['r']+q['h']; break
            if not conflict: break
        placed_top[id(o)]={'r':r,'h':h,'cols':o['cols']}
        for y,x in o['cells']: canvas[r+(y-o['top']), x]=o['col']
    # solid fall: closest-to-bottom first; blocked per column-overlap
    solids=sorted([o for o in info if not o['hole']], key=lambda o:(-(o['bot']),o['left']))
    placed_bot=[]
    crossed=False
    for o in solids:
        h=o['bot']-o['top']+1
        r=H-h
        while True:
            conflict=False
            for q in placed_bot:
                if o['cols'] & q['cols'] and r < q['r']+q['h'] and r+h > q['r']:
                    conflict=True; r=q['r']-h; break
            if not conflict: break
        # crossing check: any rising hollow whose path crosses this object's columns & rows
        deform = any((o['cols'] & ho['cols']) and (o['top'] < ho['bot']) for ho in hollows)
        if deform: crossed=True
        placed_bot.append({'r':r,'h':h,'cols':o['cols']})
        cells=[(r+(y-o['top']),x) for y,x in o['cells']]
        rep=sym_dist1(cells)
        if rep is not None: cells=rep
        elif crossed and len(hollows)>0:
            # shift top cell of the falling object right by 1 (fully-blockaded crossing)
            topy=min(c[0] for c in cells)
            tops=[c for c in cells if c[0]==topy]
            xs=[c[1] for c in cells]
            for t in tops:
                cells=[c for c in cells if c!=t]+[(t[0],t[1]+1)]
        for y,x in cells: canvas[y,x]=o['col']
    return [list(r) for r in canvas]

